item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clock,
    input  logic a,
    output logic p,
    output logic q
);
    // Intentional high-level transparent latch.
    always_latch begin
        if (clock)
            p <= a;
    end

    always_ff @(negedge clock) begin
        q <= p;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
python3 - <<'PY'
from pathlib import Path
rows=[]
for line in Path('problem.txt').read_text().splitlines():
    fields=line.split()
    if len(fields)==5 and fields[0].endswith('ns') and fields[0][:-2].isdigit():
        rows.append(fields)
s='''"'`timescale 1ns/1ps
module dev_tb;
    logic clock, a;
    wire p, q;
    integer checks = 0;
    TopModule dut (.clock(clock), .a(a), .p(p), .q(q));
    task automatic check(input logic ep, input logic eq);
        begin
            if (p !== ep || q !== eq)
                $fatal(1, "Mismatch at %0t: p=%b q=%b expected p=%b q=%b", $time, p, q, ep, eq);
            checks = checks + 1;
        end
    endtask
    initial begin
        #1000;
        $fatal(1, "Watchdog timeout");
    end
    initial begin
'"'''
for idx,(t,c,a,p,q) in enumerate(rows):
    if idx: s+='        #4;\\n'
    s+=f\"        {{clock, a}} = 2'b{c}{a};\\n        #1; check(1'b{p}, 1'b{q});\\n\"
s+='''        // Additional checks use unequal held p and current a at edges.
        #4; {clock, a} = 2'b11;
        #1; check(1'b1, 1'b0);
        #4; a = 1'b0;
        #1; check(1'b0, 1'b0);
        #4; a = 1'b1;
        #1; check(1'b1, 1'b0);
        #4; {clock, a} = 2'b00;
        #1; check(1'b1, 1'b1);
        #4; a = 1'b1;
        #1; check(1'b1, 1'b1);
        #4; a = 1'b0;
        #1; check(1'b1, 1'b1);
        #4; {clock, a} = 2'b10;
        #1; check(1'b0, 1'b1);
        #4; {clock, a} = 2'b01;
        #1; check(1'b0, 1'b0);
        "'$display("PASS: %0d waveform and directed checks", checks);
        $finish;
    end
endmodule
'"'''
Path('dev_tb.sv').write_text(s)
PY
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status="'$?
printf '"'%s\\n' \""'$compile_status" > dev_compile.exit
if [ "$compile_status" -eq 0 ]; then
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
 printf '"'%s\\n' \""'$?" > dev_simulation.exit
fi
cat contract_validation.log dev_compile.log dev_simulation.log'

